/* Catalog presentation, isolated from authentication and GPO transport. */
(() => { 'use strict';window.GpoCatalogView=Object.freeze({create({state,esc,say,tr}){
let statusIndex;
const topSections=()=>state.catalog?.sections.filter(s=>!s.parentId)||[];
const children=id=>state.catalog?.sections.filter(s=>s.parentId===id)||[];
const directRules=id=>state.catalog?.rules.filter(r=>r.sectionId===id)||[];
const descendants=id=>state.catalog?.rules.filter(r=>r.id.startsWith(id+'.'))||[];
function matchesRule(r){const q=state.query.trim().toLowerCase();const view=state.savedView==='ALL'||(state.savedView==='READY'&&r.implementation==='live')||(state.savedView==='HIGH'&&riskFor(r).cls==='high');const queryMatch=!q||(/^\d+(?:\.\d*)*$/.test(q)?r.id===q||r.id.startsWith(q.endsWith('.')?q:q+'.'):(`${r.id} ${r.title} ${r.description}`).toLowerCase().includes(q));return view&&queryMatch&&(state.level==='ALL'||r.level===state.level)&&(state.automation==='ALL'||r.automation===state.automation);}
function riskFor(r){const source=state.settings.find(x=>x.id===(r.backendSetting||r.id)),risk=GpoUiDomain.impact(source?{...source,impactReason:source.impactReason}:null);return {...risk,name:risk.name==='High'?'High':risk.name==='Medium'?'Medium':'Low'};}
function implLabel(r){if(r.implementation==='manual'||r.automation!=='Automated')return `<span class="status-chip manual">${tr('manual')}</span>`;return r.implementation==='live'?`<span class="status-chip ready">${tr('ready')}</span>`:`<span class="status-chip planned">${tr('planned')}</span>`;}
function badges(r){const scope=r.backendMapping?.scope||((r.id||'').startsWith('19.')?'User':'Computer');const label=scope==='Domain'?'ACCOUNT POLICY':scope==='User'?'USER GPO':'COMPUTER GPO';return `<span class="mini-chip">${label}</span><span class="mini-chip level">${esc(r.level)}</span><span class="mini-chip">${r.automation==='Automated'?'AUTO':'MANUAL'}</span>${implLabel(r)}`;}
function domainIcon(id){const map={'1':'⌾','2':'◇','5':'▦','9':'◫','17':'≋','18':'⚙','19':'◉'};return map[id]||'◆';}
function topDomainForRule(r){return topSections().find(s=>r.id===s.id||r.id.startsWith(s.id+'.'));}
function sectionTitle(id){return state.catalog.sections.find(s=>s.id===id)?.title||'';}
function renderSubsection(id,depth=0){const s=state.catalog.sections.find(x=>x.id===id);if(!s)return'';const kids=children(id),rules=directRules(id).filter(matchesRule),matching=descendants(id).filter(matchesRule);if(!matching.length&&!rules.length)return'';const open=state.query.trim()?!state.catalogSearchSubCollapsed?.has(id):state.expandedSub.has(id);return `<div class="ent-sub depth-${Math.min(depth,3)}"><button class="ent-sub-head" data-subsection="${esc(id)}" aria-expanded="${open}" aria-controls="catalog-subsection-${esc(id)}"><span class="sub-id">${esc(id)}</span><span class="sub-copy"><strong>${esc(s.title)}</strong><small>${matching.length||rules.length} matching · ${s.count} total</small></span><span class="chev">${open?'−':'+'}</span></button>${open?`<div id="catalog-subsection-${esc(id)}" class="ent-sub-body">${kids.map(k=>renderSubsection(k.id,depth+1)).join('')}${rules.map(renderRuleRow).join('')}</div>`:''}</div>`;}
function renderRuleRow(r){const risk=riskFor(r),status=window.GpoProduct.controlStatus(state,r,statusIndex);return `<div class="ent-rule-shell"><button class="ent-rule" data-rule="${esc(r.id)}" aria-label="Open CIS control ${esc(r.id)}: ${esc(r.title)}"><span class="rule-id">${esc(r.id)}</span><span class="rule-copy"><strong>${esc(r.title)}</strong><span class="rule-meta">${badges(r)}<span class="risk-dot ${risk.cls}">${risk.name}</span><span class="catalog-result ${esc(status.tone)}">${esc(status.label)}</span></span></span><span class="open-arrow">›</span></button></div>`;}
function renderDomain(s){const rules=descendants(s.id).filter(matchesRule),filtered=!!state.query||state.level!=='ALL'||state.automation!=='ALL'||state.savedView!=='ALL';if(!rules.length&&filtered)return'';const open=state.query.trim()?!state.catalogSearchCollapsed?.has(s.id):state.expandedTop.has(s.id);return `<section class="ent-domain domain-tone-${(Number(s.id)-1)%7} ${open?'open':''}">${window.GpoProduct.domainHeader(state,s,rules,open)}${open?`<div id="catalog-domain-${esc(s.id)}" class="ent-domain-body">${rules.length?children(s.id).map(k=>renderSubsection(k.id)).join('')+directRules(s.id).filter(matchesRule).map(renderRuleRow).join(''):`${window.GpoDomainGuidance.render(state,s,esc,say)}`}</div>`:''}</section>`;}

function benchmarkView(){statusIndex=window.GpoProduct.latestByControl(state.history);const m=state.catalog.meta,matching=state.catalog.rules.filter(matchesRule);return `<section class="library-hero"><div><span class="eyebrow">${'CIS WINDOWS SERVER 2022'}</span><h1>${'Policy library'}</h1><p>${'Find CIS controls, choose a GPO/OU target, and prepare a controlled remediation plan.'}</p></div><div class="library-version"><small>BENCHMARK</small><strong>v4.0.0</strong><span>${m.liveMappings} ${'live mappings'}</span></div></section><section class="ux-catalog-strip"><div><span>${'Controls'}</span><strong>${m.reportedRecipeCount}</strong></div><div><span>${'Automatic mappings'}</span><strong>${m.liveMappings}</strong></div><p>${'CIS sections are not AD domains; each control gets its own GPO/OU target.'}</p></section><section class="library-workbench"><div class="saved-views"><button data-view="ALL" class="${state.savedView==='ALL'?'active':''}">${'All controls'}</button><button data-view="READY" class="${state.savedView==='READY'?'active':''}">${'Remediation ready'}</button><button data-view="HIGH" class="${state.savedView==='HIGH'?'active':''}">${'High impact'}</button></div><div class="library-filterbar"><div class="searchbox"><span>⌕</span><input id="catalog-search" value="${esc(state.query)}" placeholder="${tr('search')}"></div><select id="catalog-level" aria-label="Level filter"><option value="ALL">${tr('allLevels')}</option><option value="L1" ${state.level==='L1'?'selected':''}>Level 1</option><option value="L2" ${state.level==='L2'?'selected':''}>Level 2</option><option value="NG" ${state.level==='NG'?'selected':''}>NG</option></select><select id="catalog-automation" aria-label="Automation filter"><option value="ALL">${tr('allTypes')}</option><option value="Automated" ${state.automation==='Automated'?'selected':''}>${'Automated'}</option><option value="Manual" ${state.automation==='Manual'?'selected':''}>${'Manual'}</option></select></div>${window.GpoProduct.catalogTools(state,matching.length)}<div class="domain-stack">${topSections().map(renderDomain).join('')||`<div class="empty-state" role="status"><h2>${'No matching controls'}</h2><p>${'Try another search term or adjust your filters.'}</p></div>`}</div></section>`;}

return {topSections,children,directRules,descendants,matchesRule,riskFor,implLabel,badges,topDomainForRule,sectionTitle,renderSubsection,renderRuleRow,renderDomain,benchmarkView};}});})();
